// _shared/urls.ts
export function publicUrl(input: string, base?: string): string {
  try {
    const u = new URL(input, base);
    const h = u.hostname.toLowerCase().replace(/\.$/, "");
    if (
      u.protocol !== "https:" ||
      u.username ||
      u.password ||
      (u.port && u.port !== "443") ||
      h.length > 253 ||
      !h.includes(".") ||
      h.includes(":") ||
      h.startsWith("[") ||
      /^\d+(?:\.\d+)*$/.test(h) ||
      /(?:^|\.)(?:localhost|local|internal|lan|home|test|invalid|onion)$/.test(
        h,
      )
    )
      return "";
    u.hostname = h;
    u.hash = "";
    return u.href.length <= 2048 ? u.href : "";
  } catch {
    return "";
  }
}

// _shared/metadata.ts
import { parseHTML } from "npm:linkedom@0.18.15";
export type ImportKind = "movie" | "wish" | "recipe";
export type LinkMetadata = {
  source_url: string;
  title: string;
  description: string;
  image_url: string;
  year: number | null;
  genres: string[];
  price: number | null;
  currency: string;
  ingredients: string[];
  provider: string;
};
const clean = (value: unknown, max = 1000): string => {
  if (typeof value !== "string") return "";
  return parseHTML(`<html><body>${value.slice(0, 12000)}</body></html>`)
    .document.body.textContent.replace(/\s+/g, " ")
    .trim()
    .slice(0, max);
};
function nodes(value: unknown, depth = 0): Record<string, unknown>[] {
  if (depth > 8 || !value || typeof value !== "object") return [];
  if (Array.isArray(value))
    return value.slice(0, 100).flatMap((v) => nodes(v, depth + 1));
  const o = value as Record<string, unknown>;
  return [
    o,
    ...Object.values(o)
      .slice(0, 50)
      .flatMap((v) => nodes(v, depth + 1)),
  ].slice(0, 500);
}
const types = (o: Record<string, unknown>) =>
  [o["@type"]]
    .flat()
    .filter((v): v is string => typeof v === "string")
    .map((v) => v.split("/").pop()!.toLowerCase());
function imageValue(value: unknown): string {
  if (typeof value === "string") return value;
  if (Array.isArray(value)) return imageValue(value[0]);
  if (value && typeof value === "object") {
    const o = value as Record<string, unknown>;
    return imageValue(o.url || o.contentUrl);
  }
  return "";
}
export function parseMetadata(
  html: string,
  source: string,
  kind: ImportKind,
): LinkMetadata {
  if (html.length > 1_500_000) throw new Error("Сторінка завелика.");
  const source_url = publicUrl(source);
  if (!source_url) throw new Error("Додайте повне HTTPS-посилання.");
  const { document } = parseHTML(html);
  const meta = (key: string) => {
    for (const el of document.querySelectorAll("meta"))
      if (
        (
          el.getAttribute("property") ||
          el.getAttribute("name") ||
          ""
        ).toLowerCase() === key
      )
        return el.getAttribute("content") || "";
    return "";
  };
  const structured: Record<string, unknown>[] = [];
  for (const script of Array.from(
    document.querySelectorAll('script[type="application/ld+json"]'),
  ).slice(0, 20)) {
    const text = script.textContent || "";
    if (text.length > 250000) continue;
    try {
      structured.push(...nodes(JSON.parse(text)));
    } catch {
      /* malformed JSON-LD falls back to OG */
    }
  }
  const desired =
    kind === "movie"
      ? ["movie", "tvseries", "videoobject"]
      : kind === "recipe"
        ? ["recipe"]
        : ["product"];
  const item =
    structured.find((o) => types(o).some((t) => desired.includes(t))) ?? {};
  const offer =
    nodes(item.offers).find(
      (o) => o.price !== undefined || o.lowPrice !== undefined,
    ) ?? {};
  const number = Number(
    offer.price ?? offer.lowPrice ?? meta("product:price:amount"),
  );
  const currency = clean(
    offer.priceCurrency || meta("product:price:currency"),
    8,
  ).toUpperCase();
  const yearMatch = String(item.datePublished || "").match(/^(\d{4})/);
  const year = yearMatch ? Number(yearMatch[1]) : null;
  const genres = [item.genre || []]
    .flat()
    .filter((s): s is string => typeof s === "string")
    .map((s) => clean(s, 60))
    .filter(Boolean)
    .slice(0, 8);
  const ingredients = [item.recipeIngredient || []]
    .flat()
    .filter((s): s is string => typeof s === "string")
    .map((s) => clean(s, 240))
    .filter(Boolean)
    .slice(0, 80);
  return {
    source_url,
    title: clean(
      item.name ||
        item.headline ||
        meta("og:title") ||
        meta("twitter:title") ||
        document.querySelector("title")?.textContent ||
        "",
      160,
    ),
    description: clean(
      item.description ||
        meta("og:description") ||
        meta("description") ||
        meta("twitter:description"),
    ),
    image_url: publicUrl(
      imageValue(item.image || item.thumbnailUrl) ||
        meta("og:image") ||
        meta("twitter:image"),
      source_url,
    ),
    year: year && year >= 1888 && year <= 2200 ? year : null,
    genres,
    price:
      Number.isFinite(number) &&
      number >= 0 &&
      number < 100000000 &&
      String(offer.price ?? offer.lowPrice ?? meta("product:price:amount")) !==
        ""
        ? number
        : null,
    currency,
    ingredients,
    provider: new URL(source_url).hostname.replace(/^www\./, ""),
  };
}
export function parseIngredient(line: string) {
  const fractions: Record<string, string> = {
    "½": "1/2",
    "¼": "1/4",
    "¾": "3/4",
    "⅓": "1/3",
    "⅔": "2/3",
  };
  const normalized = line
    .replace(
      /[½¼¾⅓⅔]/g,
      (c, index, text) =>
        (index > 0 && /\d/.test(text[index - 1]) ? " " : "") + fractions[c],
    )
    .trim();
  const match =
    normalized.match(
      /^(\d+(?:[.,]\d+)?(?:\s+\d+\/\d+)?|\d+\/\d+)\s*(кг|kg|г|g|л|l|мл|ml|шт\.?|pcs|cups?|tbsp|tsp|ст\.?\s*л\.?|ч\.?\s*л\.?)?\s+(.+)$/i,
    ) ??
    normalized
      .match(
        /^(.+?)\s*[-—–:]\s*(\d+(?:[.,]\d+)?)\s*(кг|kg|г|g|л|l|мл|ml|шт\.?|pcs)?$/i,
      )
      ?.map((v, i, a) =>
        i === 1 ? a[2] : i === 2 ? a[3] || "" : i === 3 ? a[1] : v,
      );
  if (!match)
    return {
      name: line.trim().slice(0, 160),
      quantity: 1,
      unit: "шт.",
      category: "Інше",
      price: null,
      note: line,
    };
  const amount = match[1]
    .replace(",", ".")
    .split(/\s+/)
    .reduce((sum, v) => {
      const parts = v.split("/").map(Number);
      return (
        sum + (parts.length === 2 && parts[1] ? parts[0] / parts[1] : parts[0])
      );
    }, 0);
  const unit =
    (
      {
        kg: "кг",
        g: "г",
        l: "л",
        ml: "мл",
        pcs: "шт.",
        шт: "шт.",
        "шт.": "шт.",
      } as Record<string, string>
    )[(match[2] || "").toLowerCase()] ||
    match[2] ||
    "шт.";
  const supported = ["кг", "г", "л", "мл", "шт."].includes(unit);
  return {
    name: (supported ? match[3] : line).trim().slice(0, 160),
    quantity:
      supported && Number.isFinite(amount) && amount > 0 && amount < 1000000
        ? Math.round(amount * 1000) / 1000
        : 1,
    unit: supported ? unit : "шт.",
    category: "Інше",
    price: null,
    note: line,
  };
}
export function parsePasted(
  text: string,
  source: string,
  kind: ImportKind,
): LinkMetadata {
  if (/<(?:html|meta|script|title|body)\b/i.test(text))
    return parseMetadata(text, source, kind);
  const lines = text
    .split("\n")
    .map((s) => s.trim().replace(/^[•*]\s*/, ""))
    .filter(Boolean);
  return {
    source_url: publicUrl(source),
    title:
      kind === "recipe"
        ? "Інгредієнти з рецепта"
        : lines[0]?.slice(0, 160) || "",
    description:
      kind === "recipe" ? "" : lines.slice(1).join(" ").slice(0, 1000),
    image_url: "",
    year: null,
    genres: [],
    price: null,
    currency: "",
    ingredients: kind === "recipe" ? lines.slice(0, 80) : [],
    provider: "Вставлений текст",
  };
}

// _shared/url-safety.ts
import ipaddr from "npm:ipaddr.js@2.5.0";
export function isPublicAddress(address: string): boolean {
  try {
    const ip = ipaddr.parse(address);
    if (ip.kind() === "ipv6" && (ip as ipaddr.IPv6).isIPv4MappedAddress())
      return (ip as ipaddr.IPv6).toIPv4Address().range() === "unicast";
    return ip.range() === "unicast";
  } catch {
    return false;
  }
}
export async function resolvePublicUrl(
  input: string,
  resolve: (host: string) => Promise<string[]>,
) {
  const safe = publicUrl(input);
  if (!safe) throw new Error("UNSAFE_URL");
  const url = new URL(safe);
  const addresses = await resolve(url.hostname);
  if (!addresses.length || addresses.some((ip) => !isPublicAddress(ip)))
    throw new Error("UNSAFE_ADDRESS");
  return { url, addresses };
}

// _shared/fetch-page.ts
import { Buffer } from "node:buffer";
import { request } from "node:https";
export const MAX_PAGE_BYTES = 1_500_000;
// Lookup is pinned to validated public DNS answers. TLS still verifies the
// ORIGINAL hostname; neither redirects nor DNS rebinding can target a LAN.
export async function fetchPublicPage(
  input: string,
  resolve: (host: string) => Promise<string[]>,
  signal: AbortSignal,
): Promise<{ html: string; url: string }> {
  let next = input;
  for (let redirects = 0; redirects <= 4; redirects++) {
    const { url, addresses } = await resolvePublicUrl(next, resolve);
    if (signal.aborted) throw new Error("TIMEOUT");
    const result = await new Promise<{
      status: number;
      location: string;
      type: string;
      body: string;
    }>((accept, reject) => {
      const address = addresses.find((a) => !a.includes(":")) || addresses[0];
      const req = request(
        url,
        {
          method: "GET",
          agent: false,
          servername: url.hostname,
          signal,
          headers: {
            Accept: "text/html,application/xhtml+xml,application/json",
            "Accept-Encoding": "identity",
            "User-Agent": "ours-link-preview/2.0",
          },
          lookup: ((
            _host: unknown,
            options: unknown,
            callback: (...args: unknown[]) => void,
          ) => {
            const family = address.includes(":") ? 6 : 4;
            if (
              options &&
              typeof options === "object" &&
              "all" in options &&
              options.all
            )
              callback(null, [{ address, family }]);
            else callback(null, address, family);
          }) as never,
        },
        (res) => {
          const status = res.statusCode || 0,
            location = String(res.headers.location || ""),
            type = String(res.headers["content-type"] || "");
          if (status >= 300 && status < 400) {
            res.destroy();
            accept({ status, location, type, body: "" });
            return;
          }
          if (
            status !== 200 ||
            !/(?:text\/html|application\/xhtml\+xml|application\/json)/i.test(
              type,
            )
          ) {
            res.destroy();
            reject(new Error("UNREADABLE_PAGE"));
            return;
          }
          if (
            Number(res.headers["content-length"] || 0) > MAX_PAGE_BYTES ||
            (res.headers["content-encoding"] &&
              res.headers["content-encoding"] !== "identity")
          ) {
            res.destroy();
            reject(new Error("UNSUPPORTED_PAGE"));
            return;
          }
          let size = 0;
          const chunks: Uint8Array[] = [];
          res.on("data", (chunk: Uint8Array) => {
            size += chunk.length;
            if (size > MAX_PAGE_BYTES) {
              res.destroy();
              reject(new Error("PAGE_TOO_LARGE"));
            } else chunks.push(chunk);
          });
          res.on("error", reject);
          res.on("end", () =>
            accept({
              status,
              location,
              type,
              body: Buffer.concat(chunks).toString("utf8"),
            }),
          );
        },
      );
      req.on("error", reject);
      req.end();
    });
    if (result.status >= 300 && result.status < 400) {
      if (!result.location || redirects === 4)
        throw new Error("REDIRECT_LIMIT");
      next = new URL(result.location, url).href;
      continue;
    }
    return { html: result.body, url: url.href };
  }
  throw new Error("REDIRECT_LIMIT");
}

// _shared/preview-handler.ts
type Dependencies = {
  origins: string[];
  authorize: (token: string) => Promise<200 | 401 | 403 | 429>;
  load: (
    url: string,
    kind: ImportKind,
    signal: AbortSignal,
  ) => Promise<LinkMetadata>;
};
async function readBody(req: Request) {
  const reader = req.body?.getReader();
  if (!reader) return "";
  const decoder = new TextDecoder();
  let size = 0,
    text = "";
  try {
    for (;;) {
      const { done, value } = await reader.read();
      if (done) break;
      size += value.length;
      if (size > 8192) {
        await reader.cancel();
        throw new Error("REQUEST_TOO_LARGE");
      }
      text += decoder.decode(value, { stream: true });
    }
    return text + decoder.decode();
  } finally {
    reader.releaseLock();
  }
}
export function createPreviewHandler({
  origins,
  authorize,
  load,
}: Dependencies) {
  return async (req: Request) => {
    const origin = req.headers.get("Origin") || "";
    const headers = {
      "Access-Control-Allow-Origin": origins.includes(origin) ? origin : "null",
      "Access-Control-Allow-Headers":
        "authorization, apikey, content-type, x-client-info",
      "Access-Control-Allow-Methods": "POST, OPTIONS",
      Vary: "Origin",
      "Cache-Control": "no-store",
      "Content-Type": "application/json",
    };
    const reply = (status: number, data: unknown) =>
      new Response(JSON.stringify(data), { status, headers });
    if (!origins.includes(origin))
      return reply(403, { error: "ORIGIN_DENIED" });
    if (req.method === "OPTIONS")
      return new Response(null, { status: 204, headers });
    if (req.method !== "POST")
      return reply(405, { error: "METHOD_NOT_ALLOWED" });
    const token = req.headers.get("Authorization") || "";
    if (!token.startsWith("Bearer ") || token.length > 8000)
      return reply(401, { error: "SIGN_IN_REQUIRED" });
    try {
      const status = await authorize(token);
      if (status !== 200)
        return reply(status, {
          error:
            status === 401
              ? "SIGN_IN_REQUIRED"
              : status === 403
                ? "SPACE_REQUIRED"
                : "TRY_LATER",
        });
      let input: { url?: string; kind?: ImportKind };
      try {
        input = JSON.parse(await readBody(req));
      } catch (e) {
        return reply(
          e instanceof Error && e.message === "REQUEST_TOO_LARGE" ? 413 : 400,
          { error: "INVALID_REQUEST" },
        );
      }
      if (
        !input ||
        typeof input.url !== "string" ||
        !["movie", "wish", "recipe"].includes(input.kind || "") ||
        !publicUrl(input.url)
      )
        return reply(400, { error: "INVALID_URL" });
      const controller = new AbortController(),
        timer = setTimeout(() => controller.abort(), 12000);
      try {
        return reply(200, {
          data: await load(input.url, input.kind!, controller.signal),
        });
      } finally {
        clearTimeout(timer);
      }
    } catch {
      return reply(422, {
        error: "CANNOT_READ_LINK",
        message: "Не вдалося прочитати сторінку. Спробуйте вставити її текст.",
      });
    }
  };
}

// link-preview/index.ts
import { createClient } from "npm:@supabase/supabase-js@2.119.0";
const origins = (
  Deno.env.get("ALLOWED_ORIGINS") || "https://hubaluna.github.io"
)
  .split(",")
  .map((s) => s.trim());
Deno.serve(
  createPreviewHandler({
    origins,
    authorize: async (authorization) => {
      const client = createClient(
        Deno.env.get("SUPABASE_URL")!,
        Deno.env.get("SUPABASE_ANON_KEY")!,
        {
          global: { headers: { Authorization: authorization } },
          auth: { persistSession: false },
        },
      );
      const {
        data: { user },
        error,
      } = await client.auth.getUser();
      if (error || !user) return 401;
      const membership = await client.rpc("current_couple");
      if (membership.error || !membership.data) return 403;
      const budget = await client.rpc("consume_link_import");
      if (budget.error || !budget.data) return 429;
      return 200;
    },
    load: async (url: string, kind: ImportKind, signal: AbortSignal) => {
      const resolve = async (host: string) => {
        const results = await Promise.allSettled([
          Deno.resolveDns(host, "A", { signal }),
          Deno.resolveDns(host, "AAAA", { signal }),
        ]);
        if (signal.aborted) throw new Error("TIMEOUT");
        return results.flatMap((r) =>
          r.status === "fulfilled" ? r.value : [],
        );
      };
      const host = new URL(url).hostname;
      if (
        kind === "movie" &&
        /(^|\.)(youtube\.com|youtu\.be|vimeo\.com)$/.test(host)
      ) {
        const endpoint = host.includes("vimeo")
          ? "https://vimeo.com/api/oembed.json"
          : "https://www.youtube.com/oembed";
        try {
          const embedded = await fetchPublicPage(
            `${endpoint}?url=${encodeURIComponent(url)}&format=json`,
            resolve,
            signal,
          );
          const value = JSON.parse(embedded.html);
          return {
            ...parseMetadata("<html></html>", url, "movie"),
            title: String(value.title || "").slice(0, 160),
            description: String(value.description || "").slice(0, 1000),
            image_url: publicUrl(value.thumbnail_url || ""),
          };
        } catch {
          /* Only actual metadata, never a guessed year or genre. */
        }
      }
      const page = await fetchPublicPage(url, resolve, signal);
      return parseMetadata(page.html, page.url, kind);
    },
  }),
);
